def definition(**overrides: object) -> YogabaseScheduleDefinition:
    settings: dict = {
        "schedule_id": "nightly",
        "function_id": "orders-nightly",
        "function_version": "1",
        "cron": "*/5 * * * *",
        "time_zone": "UTC",
        "misfire_policy": "SkipToNextOccurrence",
        "concurrency_policy": "Allow",
        "max_catch_up": 1,
        "max_attempts": 3,
        "deadline_seconds": 300,
        "payload": b"hello",
    }
    settings.update(overrides)
    return YogabaseScheduleDefinition(**settings)


def schedule_document(**overrides: object) -> dict:
    document: dict = {
        "scheduleId": "nightly",
        "projectId": PROJECT,
        "subject": "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
        "functionId": "orders-nightly",
        "functionVersion": "1",
        "version": "3",
        "instanceId": INSTANCE,
        "lastOccurrence": "2026-10-03T05:00:00+00:00",
        "oneShotAtUtc": None,
    }
    document.update(overrides)
    return {name: value for name, value in document.items() if value is not ...}


def schedule_response(request: httpx.Request, body: object, status: int = 200, etag: str | None = ETAG3) -> httpx.Response:
    headers = {"Content-Type": "application/json"}
    if etag is not None:
        headers["ETag"] = etag
    return httpx.Response(status, content=json.dumps(body).encode(), headers=headers, request=request)


def json_response(request: httpx.Request, body: object, status: int = 200) -> httpx.Response:
    return httpx.Response(status, content=json.dumps(body).encode(), headers={"Content-Type": "application/json"}, request=request)


def problem_response(request: httpx.Request, status: int, title: str, code: str | None = None, **extras: object) -> httpx.Response:
    # What ASP.NET Core writes for Results.Problem(statusCode, title, detail, extensions): the code and the
    # limits are top-level members beside type, title, status and traceId. The schedule routes name a code only
    # on the 413.
    body: dict = {"type": "https://tools.ietf.org/html/rfc9110", "title": title, "status": status, "traceId": "00-trace", **extras}
    if code is not None:
        body["code"] = code
    return httpx.Response(status, content=json.dumps(body).encode(), headers={"Content-Type": "application/problem+json"}, request=request)


class Recorder:
    """A mock transport that records each request's method, URL, headers and body."""

    def __init__(self, *responders: object) -> None:
        self.requests: list[httpx.Request] = []
        self.bodies: list[bytes] = []
        self._responders = list(responders)

    def __call__(self, request: httpx.Request) -> httpx.Response:
        self.requests.append(request)
        self.bodies.append(request.read())
        responder = self._responders.pop(0) if len(self._responders) > 1 else self._responders[0]
        return responder(request)  # type: ignore[operator]

    def client(self, **options: object) -> AsyncSchedulesClient:
        settings: dict = {"gateway_host": GATEWAY, "project_id": PROJECT, "access_token": "user-token"}
        settings.update(options)
        return AsyncSchedulesClient(http_client=httpx.AsyncClient(transport=httpx.MockTransport(self)), **settings)


def run_deadline() -> datetime:
    return datetime.now(timezone.utc) + timedelta(minutes=10)


class ScheduleCreateAndUpdateTests(unittest.IsolatedAsyncioTestCase):
    async def test_create_sends_a_conditional_put_of_the_exact_body_and_reads_the_schedule_and_its_etag(self) -> None:
        recorder = Recorder(lambda request: schedule_response(request, schedule_document(version="1"), 201, f'"schedule-v1-{INSTANCE_HEX}"'))
        async with recorder.client() as schedules:
            created = await schedules.create(definition())

        request = recorder.requests[0]
        self.assertEqual((request.method, str(request.url)), ("PUT", ITEM))
        self.assertEqual(request.headers["Authorization"], "Bearer user-token")
        self.assertEqual(request.headers["Content-Type"], "application/json")
        # Exactly one of the two preconditions: a create is conditional on there being nothing there.
        self.assertEqual(request.headers["If-None-Match"], "*")
        self.assertNotIn("If-Match", request.headers)
        # The names are the gateway's ScheduledLambdaDefinitionRequest, which refuses any other member.
        self.assertEqual(
            recorder.bodies[0],
            b'{"scheduleId":"nightly","functionId":"orders-nightly","functionVersion":"1","cron":"*/5 * * * *","timeZone":"UTC",'
            b'"misfirePolicy":"SkipToNextOccurrence","concurrencyPolicy":"Allow","maxCatchUp":1,"maxAttempts":3,"deadlineSeconds":300,'
            b'"payloadBase64":"aGVsbG8="}',
        )
        self.assertEqual(created.schedule_id, "nightly")
        self.assertEqual(created.project_id, PROJECT)
        self.assertEqual(created.subject, "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa")
        self.assertEqual((created.function_id, created.function_version, created.version), ("orders-nightly", "1", "1"))
        self.assertEqual(created.instance_id, INSTANCE)
        self.assertEqual(created.last_occurrence, "2026-10-03T05:00:00+00:00")
        self.assertIsNone(created.one_shot_at_utc)
        self.assertFalse(created.is_one_shot)
        self.assertEqual(created.etag, f'"schedule-v1-{INSTANCE_HEX}"')

    async def test_update_sends_the_etag_as_if_match_and_never_if_none_match(self) -> None:
        recorder = Recorder(lambda request: schedule_response(request, schedule_document(version="4"), 200, f'"schedule-v4-{INSTANCE_HEX}"'))
        async with recorder.client() as schedules:
            updated = await schedules.update(definition(), ETAG3)

        request = recorder.requests[0]
        self.assertEqual((request.method, str(request.url)), ("PUT", ITEM))
        self.assertEqual(request.headers["If-Match"], ETAG3)
        self.assertNotIn("If-None-Match", request.headers)
        self.assertEqual((updated.version, updated.etag), ("4", f'"schedule-v4-{INSTANCE_HEX}"'))

    async def test_a_definition_omits_an_absent_or_empty_payload_and_sends_a_one_shots_instant_in_utc(self) -> None:
        recorder = Recorder(lambda request: schedule_response(request, schedule_document(), 201))
        seoul = timezone(timedelta(hours=9))
        async with recorder.client() as schedules:
            await schedules.create(definition(payload=None))
            await schedules.create(definition(payload=b""))
            await schedules.create(definition(payload=None, one_shot_at_utc=datetime(2026, 10, 3, 12, 0, tzinfo=seoul)))
        # A schedule with no payload and one with an empty payload are the same schedule to the gateway.
        self.assertNotIn(b"payloadBase64", recorder.bodies[0])
        self.assertEqual(recorder.bodies[0], recorder.bodies[1])
        self.assertNotIn(b"oneShotAtUtc", recorder.bodies[0])
        # 12:00 at +09:00 is 03:00 UTC, and the gateway requires a UTC instant.
        self.assertTrue(recorder.bodies[2].endswith(b',"oneShotAtUtc":"2026-10-03T03:00:00+00:00"}'), recorder.bodies[2])

    async def test_every_policy_is_sent_by_its_name(self) -> None:
        recorder = Recorder(lambda request: schedule_response(request, schedule_document(), 201))
        cases = [("RunImmediately", "Allow"), ("SkipToNextOccurrence", "Forbid"), ("RunAllMissed", "Replace")]
        async with recorder.client() as schedules:
            for misfire, concurrency in cases:
                await schedules.create(definition(misfire_policy=misfire, concurrency_policy=concurrency))
        self.assertEqual(
            [(json.loads(body)["misfirePolicy"], json.loads(body)["concurrencyPolicy"]) for body in recorder.bodies],
            cases,
        )

    async def test_a_payload_at_exactly_the_inline_limit_is_sent_and_one_byte_more_is_refused_before_the_network(self) -> None:
        recorder = Recorder(lambda request: schedule_response(request, schedule_document(), 201))
        async with recorder.client() as schedules:
            await schedules.create(definition(payload=bytes(YOGABASE_SCHEDULES_MAXIMUM_PAYLOAD_BYTES)))
            self.assertEqual(len(json.loads(recorder.bodies[0])["payloadBase64"]), 1_398_104)
            over = definition(payload=bytes(YOGABASE_SCHEDULES_MAXIMUM_PAYLOAD_BYTES + 1))
            with self.assertRaises(ValueError):
                await schedules.create(over)
            with self.assertRaises(ValueError):
                await schedules.update(over, ETAG3)
        self.assertEqual(len(recorder.requests), 1)

